/* ── Brimstone — Caleb's Hollow Hex Game ────────────────────────────────── */

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg:           #0d0f16;
  --bg-panel:     #111520;
  --bg-section:   #161b28;
  --border:       #2a2040;
  --text:         #d4c9b0;
  --text-dim:     #7a7060;
  --text-bright:  #f0e8d0;
  --hero:         #d4a72c;
  --witch:        #9b59b6;
  --day:          #f5c842;
  --night:        #7b4fbb;
  --green:        #4caf7d;
  --red:          #c0392b;
  --font-serif:   "Georgia", "Times New Roman", serif;
  --font-mono:    "Courier New", monospace;
}

html, body {
  height: 100%;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font-serif);
  font-size: 14px;
  line-height: 1.5;
  overflow: hidden;
}

/* Prevent tap highlight flash and double-tap zoom on interactive elements */
button, canvas { -webkit-tap-highlight-color: transparent; touch-action: manipulation; }
/* pan-x pan-y: browser handles scroll gestures; JS handles taps */
canvas { touch-action: pan-x pan-y; }

/* ── Setup screen ──────────────────────────────────────────────────────── */

#setup-screen {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 100vh;
  background: url('assets/bg.png') center/cover no-repeat;

input.old_string:
#game-canvas {
  display: block;
  cursor: pointer;
  image-rendering: pixelated;
}

input.new_string:
#game-canvas {
  display: block;
  cursor: pointer;
  image-rendering: pixelated;
  /* Hidden until the loading overlay reveals it — main.js adds .canvas-ready
     once renderer.whenReady() resolves and the first full-quality frame is
     drawn, fading the scene in instead of showing the procedural fallbacks. */
  opacity: 0;
  transition: opacity 400ms ease-in;
}
#game-canvas.canvas-ready { opacity: 1; }

/* ── Loading overlay ────────────────────────────────────────────────────── */

#loading-overlay {
  position: absolute;
  inset: 0;
  z-index: 50;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  opacity: 1;
  /* [hidden] still wins (display:none) — this only animates the fade-out. */
  transition: opacity 300ms ease-out;
}
#loading-overlay.fading-out { opacity: 0; }

.loading-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1.1rem;
  padding: 2rem 2.5rem;
  text-align: center;
}

.loading-title {
  font-family: var(--font-serif);
  font-size: 1.8rem;
  letter-spacing: 0.04em;
  color: var(--text-bright);
  text-shadow: 0 2px 8px rgba(0, 0, 0, 0.6);
}

.loading-bar {
  width: min(60vw, 320px);
  height: 8px;
  background: var(--bg-section);
  border: 1px solid var(--border);
  border-radius: 5px;
  overflow: hidden;
}

.loading-bar-fill {
  width: 0%;
  height: 100%;
  background: linear-gradient(90deg, var(--witch), var(--hero));
  /* Width is driven by inline style from main.js as items settle. */
  transition: width 200ms ease-out;
}

.loading-label {
  font-family: var(--font-mono);
  font-size: 0.85rem;
  color: var(--text-dim);
  letter-spacing: 0.03em;
}

