function _doRestart() {
  // Disconnect from server if in online mode
  if (mp) { mp.disconnect(); mp = null; }

  // Clean up AI debug state
  _clearAIDebug();
  setAIDebugActive(false);

  // Reset game objects so initOnline / init start fresh
