            const toPos   = path[hop];
            renderer.addMoveAnim(
              ev.action.entityId,
              fromPos.col, fromPos.row,
              toPos.col, toPos.row,
              preSnap.type, preSnap.owner,
              preSnap.title ?? null,
            );
