        await playbackDelay(_spd4 === 'vfast' ? 140 : 240);
        renderer.returnAllLungeAnims();
        await renderer.waitForAnimations();
        redrawFn();
      }
    }

    // ── Phase 2a: empty-hex attack whiffs (lunge + "no enemy" floater) ───────
