    _stopMmCountdown?.();
  }

  stepMode          .style.display = step === 'mode'            ? '' : 'none';
  stepSinglePlayer  .style.display = step === 'singleplayer'    ? '' : 'none';
  stepCampaignSelect.style.display = step === 'campaign-select' ? '' : 'none';
